import{_ as a}from"./chunks/viewer.mLrqh1Y4.js";import{_ as t,o as s,c as i,ao as o}from"./chunks/framework.DAbzcW3k.js";const n="/TerraScope.jl/dev/assets/launcher.CM5T3o06.png",m=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting_started.md","filePath":"getting_started.md","lastUpdated":null}'),l={name:"getting_started.md"};function h(r,e,p,d,c,u){return s(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="Getting-Started" tabindex="-1">Getting Started <a class="header-anchor" href="#Getting-Started" aria-label="Permalink to &quot;Getting Started {#Getting-Started}&quot;">​</a></h1><p>This page takes you from an empty computer to an open TerraScope window. You do not need to know Julia. You must know how to open a terminal and how to edit a text file.</p><h2 id="1.-Install-Julia" tabindex="-1">1. Install Julia <a class="header-anchor" href="#1.-Install-Julia" aria-label="Permalink to &quot;1. Install Julia {#1.-Install-Julia}&quot;">​</a></h2><p>TerraScope needs Julia 1.12 or newer. We recommend Julia 1.13.0, because it precompiles faster. Thus the first start of TerraScope takes less time.</p><p>Get Julia from <a href="https://julialang.org/downloads/" target="_blank" rel="noreferrer">julialang.org/downloads</a>. The page recommends <code>juliaup</code>, a small tool that installs Julia and keeps it up to date. Use it. Then install Julia 1.13.0 and make it the default:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">juliaup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.13.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">juliaup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> default</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.13.0</span></span></code></pre></div><p>To make sure that the installation is correct, open a new terminal and type:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>The terminal must show <code>julia version 1.13.0</code>. If it shows an error, the terminal cannot find Julia. Close the terminal, open a new one and try again.</p><h2 id="2.-Get-TerraScope" tabindex="-1">2. Get TerraScope <a class="header-anchor" href="#2.-Get-TerraScope" aria-label="Permalink to &quot;2. Get TerraScope {#2.-Get-TerraScope}&quot;">​</a></h2><p>Download the code and go into its folder:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/JuliaGeophysics/TerraScope.jl</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> TerraScope.jl</span></span></code></pre></div><p>Install the packages that TerraScope needs:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;using Pkg; Pkg.instantiate()&quot;</span></span></code></pre></div><p>What does this command do? <code>--project=.</code> tells Julia to use the package list in the current folder. <code>Pkg.instantiate()</code> downloads and installs all packages in that list. You do this one time only. It can take 10 minutes or more.</p><h2 id="3.-Tell-TerraScope-where-your-files-are" tabindex="-1">3. Tell TerraScope where your files are <a class="header-anchor" href="#3.-Tell-TerraScope-where-your-files-are" aria-label="Permalink to &quot;3. Tell TerraScope where your files are {#3.-Tell-TerraScope-where-your-files-are}&quot;">​</a></h2><p>Open <code>examples/launch_TerraScope3D.jl</code> in a text editor. This is the only file that you edit. It has three sections:</p><ol><li><p><strong>Inputs</strong>: the model and data files to load. See <a href="./inputs">Inputs</a>.</p></li><li><p><strong>Shapefiles</strong>: the linework to show. Each line has its own <code>color</code>, <code>width</code> and <code>alpha</code>.</p></li><li><p><strong>Settings</strong>: display, view, CRS, seismic, overlay and isosurface options. See <a href="./settings">Launcher settings</a>.</p></li></ol><p>The file contains example paths. They are not correct on your computer. Replace them with the paths to your files, or use <code>&quot;&quot;</code> for an input that you do not have.</p><p>Let us look at one line:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MT_model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> raw</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;C:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ata</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">urvey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">odel.rho&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span></code></pre></div><ul><li><p><code>MT_model</code> is the name of the input. Do not change it.</p></li><li><p><code>raw&quot;...&quot;</code> is a text that Julia reads exactly as written. Use it for Windows paths, because then you do not have to double each <code>\\</code>.</p></li><li><p>The comma at the end is necessary. Do not remove it.</p></li></ul><p>To ignore an input, write <code>MT_model = &quot;&quot;,</code>.</p><h2 id="4.-Open-the-viewer" tabindex="-1">4. Open the viewer <a class="header-anchor" href="#4.-Open-the-viewer" aria-label="Permalink to &quot;4. Open the viewer {#4.-Open-the-viewer}&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/launch_TerraScope3D.jl</span></span></code></pre></div><p>On Windows, you can also double-click <code>Launch-TerraScope.cmd</code> in the repository folder. See <a href="./startup">Faster startup</a>.</p><p>The first start is slow, because Julia compiles the code before it runs it. The next starts are faster. To make them faster again, see <a href="./startup">Faster startup</a>.</p><p>The launcher first checks each path. Then it shows the progress:</p><p><img src="`+n+'" alt=""></p><p>A <code>✗</code> shows a path that is not correct. Correct the path and start again.</p><h2 id="5.-Use-the-viewer" tabindex="-1">5. Use the viewer <a class="header-anchor" href="#5.-Use-the-viewer" aria-label="Permalink to &quot;5. Use the viewer {#5.-Use-the-viewer}&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>The 3D scene is in the center. The controls are at the bottom.</p><p>The property buttons select the volume. The scene, the sections, the isosurfaces and the exports use the selected volume. If there is no file for a property, its button shows <code>N/A</code>.</p><p><strong>Show Data</strong> shows the measured data for the property on the screen. For example, select density and push <strong>Show Data</strong>. The viewer then shows the gravity survey points.</p><h2 id="When-something-goes-wrong" tabindex="-1">When something goes wrong <a class="header-anchor" href="#When-something-goes-wrong" aria-label="Permalink to &quot;When something goes wrong {#When-something-goes-wrong}&quot;">​</a></h2><ul><li><p><strong><code>julia</code> is not found.</strong> Julia is not on your <code>PATH</code>. Install Julia again with <code>juliaup</code>, then open a new terminal.</p></li><li><p><strong>A path shows <code>✗</code>.</strong> The file is not at that location. Copy the full path from your file manager and paste it between the quotes of <code>raw&quot;...&quot;</code>.</p></li><li><p><strong>The scene has no shapefiles or survey points.</strong> The MT model is not georeferenced. Add the <code>MT_data</code> file. See <a href="/TerraScope.jl/dev/inputs#what-you-get">What you get</a>.</p></li></ul>',37)])])}const y=t(l,[["render",h]]);export{m as __pageData,y as default};
